content:
:root {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  line-height: 1.5;
  color: #333;
  background-color: #f8fafc;
}

body {
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
}

* {
  box-sizing: border-box;
}

.app-container {
  width: 100%;
  max-width: 900px;
  margin: 2rem auto;
  padding: 2rem;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.header {
  margin-bottom: 1.5rem;
}

.title {
  margin: 0 0 1rem 0;
  font-size: 1.75rem;
  font-weight: 700;
  color: #1e293b;
}

.filter-container {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.filter-input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.filter-input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
  display: block;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.employee-table th,
.employee-table td {
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}

.employee-table tbody tr:hover {
  background-color: #f1f5f9;
}

.sortable-header {
  cursor: pointer;
  user-select: none;
  background-color: #f8fafc;
  font-weight: 600;
  color: #475569;
  transition: background-color 0.3s cubic-bezier(0.4, 0, 0.2, 1), color 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.sortable-header:hover {
  background-color: #e2e8f0;
  color: #1e293b;
}

.badge {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  font-size: 0.8rem;
  font-weight: 500;
  color: #0369a1;
  background-color: #e0f2fe;
  border-radius: 9999px;
}

.no-results {
  text-align: center;
  padding: 3rem 1rem;
  color: #64748b;
  font-size: 1rem;
}

@media (max-width: 640px) {
  .app-container {
    margin: 0;
    padding: 1rem;
    border-radius: 0;
    min-height: 100vh;
  }

  .employee-table th,
  .employee-table td {
    padding: 0.75rem 0.5rem;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export type SortField = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

export interface FilterOptions {
  name?: string;
  department?: string;
  minAge?: number;
  maxAge?: number;
}

export interface PaginationOptions {
  page: number;
  pageSize: number;
}

import { useState, useMemo } from 'react';
import { Employee, SortField, SortOrder } from './types';
import './index.css';

const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健', department: '開発部', age: 28 },
  { id: 2, name: '鈴木 美咲', department: '人事部', age: 34 },
  { id: 3, name: '高橋 翔', department: '営業部', age: 41 },
  { id: 4, name: '田中 葵', department: '開発部', age: 25 },
  { id: 5, name: '渡辺 蓮', department: 'マーケティング部', age: 30 },
  { id: 6, name: '伊藤 陽菜', department: '営業部', age: 27 },
  { id: 7, name: '山本 拓海', department: '開発部', age: 36 },
  { id: 8, name: '中村 さくら', department: '人事部', age: 29 },
  { id: 9, name: '小林 悠真', department: 'マーケティング部', age: 32 },
  { id: 10, name: '加藤 美優', department: '営業部', age: 24 },
];

export default function App() {
  const [filterText, setFilterText] = useState('');
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const filteredEmployees = useMemo(() => {
    return initialEmployees.filter((employee) =>
      employee.name.toLowerCase().includes(filterText.toLowerCase())
    );
  }, [filterText]);

  const sortedEmployees = useMemo(() => {
    return [...filteredEmployees].sort((a, b) => {
      let aVal = a[sortField];
      let bVal = b[sortField];

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comparison = aVal.localeCompare(bVal, 'ja');
        return sortOrder === 'asc' ? comparison : -comparison;
      } else {
        if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      }
    });
  }, [filteredEmployees, sortField, sortOrder]);

  return (
    <div className="app-container">
      <div className="header">
        <h1 className="title">社員一覧</h1>
        <div className="filter-container" style={{ position: 'relative' }}>
          <input
            type="text"
            className="filter-input"
            placeholder="名前で絞り込み..."
            value={filterText}
            onChange={(e) => setFilterText(e.target.value)}
          />
          {filterText && (
            <button
              type="button"
              onClick={() => setFilterText('')}
              style={{
                position: 'absolute',
                right: '1rem',
                top: '50%',
                transform: 'translateY(-50%)',
                background: 'transparent',
                border: 'none',
                cursor: 'pointer',
                fontSize: '1rem',
                color: '#64748b',
                padding: '0 0.25rem',
              }}
              aria-label="検索をクリア"
            >
              ✕
            </button>
          )}
        </div>
      </div>

      {sortedEmployees.length === 0 ? (
        <div className="no-results">
          一致する社員が見つかりませんでした。
        </div>
      ) : (
        <table className="employee-table">
          <thead>
            <tr>
              <th
                className="sortable-header"
                onClick={() => handleSort('name')}
                aria-sort={
                  sortField === 'name'
                    ? sortOrder === 'asc'
                      ? 'ascending'
                      : 'descending'
                    : 'none'
                }
              >
                名前 {sortField === 'name' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
              <th
                className="sortable-header"
                onClick={() => handleSort('department')}
                aria-sort={
                  sortField === 'department'
                    ? sortOrder === 'asc'
                      ? 'ascending'
                      : 'descending'
                    : 'none'
                }
              >
                部署 {sortField === 'department' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
              <th
                className="sortable-header"
                onClick={() => handleSort('age')}
                aria-sort={
                  sortField === 'age'
                    ? sortOrder === 'asc'
                      ? 'ascending'
                      : 'descending'
                    : 'none'
                }
              >
                年齢 {sortField === 'age' && (sortOrder === 'asc' ? '▲' : '▼')}
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedEmployees.map((employee) => (
              <tr key={employee.id}>
                <td>{employee.name}</td>
                <td>
                  <span className="badge">{employee.department}</span>
                </td>
                <td>{employee.age}歳</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
